    for i in range(9):
        c=b[o+i]
        if i==8:
            v=(v<<8)|c; return v,o+9
        v=(v<<7)|(c&0x7f)
        if not c&0x80: return v,o+i+1
ncell=struct.unpack('>H',d[3:5])[0]
print('ncell',ncell)
ptrs=[struct.unpack('>H',d[8+2*i:10+2*i])[0] for i in range(ncell)]
def serial_val(t,b):
    import struct as s
    if t==0:return None
    if t==1:return b[0]-256 if b[0]>127 else b[0]
    if t==2:return int.from_bytes(b,'big',signed=True)
    if t==3:return int.from_bytes(b,'big',signed=True)
    if t==4:return int.from_bytes(b,'big',signed=True)
    if t==5:return int.from_bytes(b,'big',signed=True)
    if t==6:return int.from_bytes(b,'big',signed=True)
    if t==7:return s.unpack('>d',b)[0]
    if t==8:return 0
    if t==9:return 1
    return b
def sertype_len(t):
    if t<5:return [0,1,2,3,4,6][t] if t<6 else 0
    return t
lens={0:0,1:1,2:2,3:3,4:4,5:6,6:8,7:8,8:0,9:0}
rows=[]
for p in ptrs:
    o=p
    plen,o=varint(d,o)
    rowid,o=varint(d,o)
    hstart=o
    hlen,o2=varint(d,o)
    types=[]
    oo=o2
    while oo<hstart+hlen:
        t,oo=varint(d,oo)
        types.append(t)
    body=oo
    vals=[]
    for t in types:
        if t>=12:
            L=(t-12)//2 if t%2==0 else (t-13)//2
        else:
            L=lens.get(t,0)
        raw=d[body:body+L]
        vals.append(serial_val(t,raw))
        body+=L
    rows.append((rowid,vals,types))
for r in rows: print(r)
